BEGIN;
DO $$DECLARE a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();h uuid:=gen_random_uuid();other_h uuid:=gen_random_uuid();g uuid:=gen_random_uuid();t uuid:=gen_random_uuid();r jsonb;replay jsonb;learning text;rule text:='Wenn die Zone fehlt, dann warte ich auf einen klaren Test.';denied boolean;
BEGIN
INSERT INTO auth.users(id,aud,role) VALUES(a,'authenticated','authenticated'),(b,'authenticated','authenticated');
INSERT INTO public.trading_sessions(id,owner_id,session_date,htf_context) VALUES(h,a,(clock_timestamp() AT TIME ZONE 'Europe/Berlin')::date,'{}'),(other_h,b,(clock_timestamp() AT TIME ZONE 'Europe/Berlin')::date,'{}');
INSERT INTO public.v8_htf_assessments(id,owner_id,session_id,captured_at,plan) VALUES(h,a,h,now()-interval '3 hours','{"direction":"long"}'),(other_h,b,other_h,now()-interval '3 hours','{"direction":"short"}');
PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
EXECUTE 'SET LOCAL ROLE authenticated';
learning:='@TT809:'||jsonb_build_object('points',jsonb_build_object('technical','confirmed'),'actual',jsonb_build_object('technical','Trend folgte'),'condition','','note','Kontext und Trigger getrennt prüfen.','training_rule',rule)::text;
r:=public.review_htf_assessment_v809(h,NULL,'confirmed',learning,false);
IF r->>'reviewed_at' IS NULL THEN RAISE EXCEPTION 'Missing acknowledgement';END IF;
replay:=public.review_htf_assessment_v809(h,NULL,'confirmed',learning,false);
IF r->>'reviewed_at'<>replay->>'reviewed_at' THEN RAISE EXCEPTION 'Replay changed timestamp';END IF;
denied:=false;BEGIN PERFORM public.review_htf_assessment_v809(h,NULL,'partial',learning||' ',false);EXCEPTION WHEN raise_exception THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Stale learning overwritten';END IF;
denied:=false;BEGIN PERFORM public.review_htf_assessment_v809(other_h,NULL,'confirmed',learning,false);EXCEPTION WHEN raise_exception THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Foreign assessment accessible';END IF;
PERFORM public.set_htf_training_focus_v809(g,NULL,h,rule);
IF NOT EXISTS(SELECT 1 FROM public.training_goals_v7 WHERE id=g AND source_htf_id=h) THEN RAISE EXCEPTION 'HTF source lost';END IF;
denied:=false;BEGIN UPDATE public.training_goals_v7 SET source_htf_id=other_h WHERE id=g;EXCEPTION WHEN raise_exception THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Foreign training reference accepted';END IF;
EXECUTE 'RESET ROLE';
INSERT INTO public.trades(id,owner_id,session_id,setup_type,instrument,direction,entry_at,observations) VALUES(t,a,h,'V809 synthetic','MNQ','long',now()-interval '1 day','{}');
EXECUTE 'SET LOCAL ROLE authenticated';
IF NOT EXISTS(SELECT 1 FROM public.trades WHERE id=t AND observations#>>'{training_focus,source_htf_id}'=h::text) THEN RAISE EXCEPTION 'Entry snapshot lost HTF source';END IF;
r:=public.close_historical_trade_v809(t,'manual',NULL,'Damals keine Gefühle dokumentiert.');
IF r->>'pending'<>'true' OR NOT EXISTS(SELECT 1 FROM public.trades WHERE id=t AND realized_pnl_usd IS NULL AND observations->>'exit_emotions_unknown'='true' AND NOT observations?'exit_emotion_scales') THEN RAISE EXCEPTION 'Historical unknown values invented';END IF;
replay:=public.close_historical_trade_v809(t,'manual',NULL,'Damals keine Gefühle dokumentiert.');
IF replay->>'trade_id'<>t::text THEN RAISE EXCEPTION 'Historical replay failed';END IF;
IF NOT public.valid_setup_media_v809('{"pattern":{"scale":2,"x":30,"y":90}}',a) OR public.valid_setup_media_v809('{"pattern":{"scale":5,"x":0,"y":0}}',a) THEN RAISE EXCEPTION 'Crop range incorrect';END IF;
IF public.valid_setup_media_v809(jsonb_build_object('examples',jsonb_build_object(t::text,jsonb_build_object('scale',1,'x',50,'y',50,'path',b::text||'/trade/'||t::text||'/x.png'))),a) THEN RAISE EXCEPTION 'Foreign media path accepted';END IF;
PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);
IF EXISTS(SELECT 1 FROM public.trades WHERE id=t) THEN RAISE EXCEPTION 'Foreign trade visible';END IF;
denied:=false;BEGIN PERFORM public.close_historical_trade_v809(t,'manual',NULL,'Foreign request');EXCEPTION WHEN raise_exception THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Foreign exit accepted';END IF;
EXECUTE 'RESET ROLE';
END $$;
ROLLBACK;
SELECT 'V8.09 SQL ownership, crop, CAS, replay, source snapshot and historical-exit checks passed' AS result;
